result=js(r'''(async()=>{
const T=await import('three'),r=await import('./js/world/city-rollout.js'),kit=await import('./js/world/building-kit.js'),{townhouseMaterials}=await import('./js/world/building-slice-materials.js'),{stops}=await import('./js/content.js'),{routePoints,routeCurve}=await import('./js/world/layout.js'),{buildCity}=await import('./js/world/city.js');const check=(v,m)=>{if(!v)throw Error(m)},pts=routePoints(stops.length),plots=[];buildCity(()=>{},stops,pts,routeCurve(T,pts),undefined,undefined,p=>plots.push(p));
check(r.classifyPlot({kind:'midrise',width:10,depth:10,height:6})==='midrise','compact residential recipe preserves low envelopes');check(r.classifyPlot({kind:'terrace',width:6,depth:9,height:6})==='townhouse','compatible low terraces');
const source=JSON.stringify(plots),city=kit.createCityBuildings(plots),g=city.getObjectByName('citywide-architecture');check(g&&g.userData.plotIds.length>250,'existing compatible city lots converted');check(JSON.stringify(plots)===source,'source descriptors unchanged');check(plots.filter(p=>r.classifyCompletion(p)==='B').every(p=>!g.userData.plotIds.includes(p.id)),'special plots preserved');check(g.userData.plotIds.filter(id=>r.classifyCompletion(plots.find(p=>p.id===id))).length===81,'exactly 81 safe completion plots');check(new Set(g.userData.plotIds).size===g.userData.plotIds.length,'no duplicate lots');check(g.children.every(c=>c.children.length===3),'three stable meshes per occupied cell');
const shared=townhouseMaterials(),materials=new Set,maps=new Set;let triangles=0,renderables=0,bytes=0;
for(const c of g.children){const own=plots.filter(p=>c.userData.plotIds.includes(p.id));check(own.length>0,'no empty cells');for(const lod of c.userData.lods){for(const geometry of lod){check(geometry.boundingBox&&geometry.boundingSphere,'bounds');bytes+=Object.values(geometry.attributes).reduce((n,a)=>n+a.array.byteLength,0);const a=geometry.attributes;for(const key of ['normal','uv','aSurface','color'])check(a[key]?.count===a.position.count,'merge attributes');for(let i=0;i<a.position.count;i++){const x=a.position.getX(i)+c.position.x,y=a.position.getY(i),z=a.position.getZ(i)+c.position.z;check(own.some(p=>Math.abs(x-p.x)<=p.width/2+.001&&Math.abs(z-p.z)<=p.depth/2+.001&&y>=-.001&&y<=p.height+.001),'source footprint/height');}}}c.children.forEach((m,k)=>{renderables++;triangles+=m.geometry.attributes.position.count/3;materials.add(m.material);Object.values(m.material).forEach(v=>{if(v?.isTexture)maps.add(v)});check(m.castShadow===(k===0)&&m.frustumCulled&&m.material===(k===2?shared.glass:shared.architecture),'render policy/shared identities');});}
check(materials.size===2&&maps.size===4&&renderables===g.children.length*3,'shared resources/batching');check(triangles<=750000&&bytes<=180*1024*1024,'citywide geometry ceiling');
const fp=o=>{const a=[];o.traverse(m=>{if(m.isMesh)a.push({name:m.name,position:m.position.toArray(),attributes:Object.fromEntries(Object.entries(m.geometry.attributes).map(([k,v])=>[k,Array.from(v.array)])),instances:m.instanceMatrix?Array.from(m.instanceMatrix.array):null})});return JSON.stringify(a)};
const old=kit.createCityBuildings(plots,{rollout:false}),protectedNames=['townhouse-benchmark-chunk','townhouse-experiment','hero-shopfronts','hero-final-frontages','hero-zone-architecture','hero-background-cleanup','hero-adjacent-region','block--279--49','midrise-replication','block--183--37','block--295--49'];for(const name of protectedNames)check(fp(city.getObjectByName(name))===fp(old.getObjectByName(name)),'approved control unchanged '+name);
const {buildSaoPaulo}=await import('./js/world/saopaulo.js'),decor=[];buildSaoPaulo(()=>{},stops,pts,p=>decor.push(p),true);check(decor.length===8,'eight existing decorative envelopes');const extra=r.createCityRollout(decor.filter(p=>!p.id.startsWith('paulista-hero-')));check(extra.userData.plotIds.length===6,'six additional existing decorative towers');const selected=plots.filter(p=>g.userData.plotIds.includes(p.id)),small=r.createCityRollout(selected.slice(0,4),plots),reversed=r.createCityRollout(selected.slice(0,4).reverse(),plots);check(fp(small)===fp(reversed),'input-order determinism');for(const c of small.children){const d=c.userData,near=new T.Vector3(d.bounds.max.x,2,d.bounds.max.z);small.userData.update({position:near});check(d.level===0,'initial LOD0');small.userData.update({position:near.clone().add(new T.Vector3(140,0,0))});check(d.level===1||d.lods.length===1,'supported LOD1');}let disposed=0;g.children.forEach(c=>c.userData.lods.flat().forEach(geometry=>geometry.addEventListener('dispose',()=>disposed++)));g.userData.dispose();g.userData.dispose();check(disposed===g.children.reduce((n,c)=>n+c.userData.lods.flat().length,0),'dispose each resident geometry once');return {pass:true,converted:g.userData.counts,lots:g.userData.plotIds.length,chunks:g.children.length,renderables,triangles,materials:materials.size,maps:maps.size,geometryMiB:bytes/1024/1024,completion:g.userData.plotIds.reduce((n,id)=>{const category=r.classifyCompletion(plots.find(p=>p.id===id));if(category)n[category]=(n[category]||0)+1;return n},{}),preserved:plots.filter(p=>!g.userData.plotIds.includes(p.id)).map(p=>({id:p.id,kind:p.kind,height:p.height})),decorative:extra.userData.counts,decorativeChunks:extra.children.length};})()''')
